  /**
   * @method
   * @name btcturk#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://docs.btcturk.com/private-endpoints/user-transactions
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any response =
                     awaitValue(this->privateGetUsersTransactionsTrade());
                 //
                 //     {
                 //       "data": [
                 //         {
                 //           "price": "56000",
                 //           "numeratorSymbol": "BTC",
                 //           "denominatorSymbol": "USDT",
                 //           "orderType": "buy",
                 //           "orderId": "2606935102",
                 //           "id": "320874372",
                 //           "timestamp": "1618916479593",
                 //           "amount": "0.00020000",
                 //           "fee": "0",
                 //           "tax": "0"
                 //         }
                 //       ],
                 //       "success": true,
                 //       "message": "SUCCESS",
                 //       "code": "0"
                 //     }
                 //
                 ccxt::any data = this->safeList(response, std::string("data"));
                 ccxt::any dataList = ccxt::list{};
                 if (isTrue(!isEqual(data, ccxt::any{}))) {
                   dataList = data;
                 }
                 return this->parseTrades(dataList, market, since, limit);
               })
        .share();
  }

  ccxt::any nonce() override { return this->milliseconds(); }

  ccxt::any sign(ccxt::any path, ccxt::any api = std::string("public"),
                 ccxt::any method = std::string("GET"),
                 ccxt::any params = ccxt::dict{},
                 ccxt::any headers = ccxt::any{},
                 ccxt::any body = ccxt::any{}) override {
    if (isTrue(isEqual(this->id, std::string("btctrader")))) {
      throw ExchangeError(toString(add(
          this->id,
          std::string(" is an abstract base API for BTCExchange, BTCTurk"))));
    }
    ccxt::any url =
        add(add(::getValue(::getValue(this->urls, std::string("api")), api),
                std::string("/")),
            path);
    if (isTrue(isTrue((isEqual(method, std::string("GET")))) ||
               isTrue((isEqual(method, std::string("DELETE")))))) {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(params)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(params)));
      }
    } else {
      body = this->json(params);
    }
    if (isTrue(isEqual(api, std::string("private")))) {
      this->checkRequiredCredentials();
      ccxt::any nonce = toString(this->nonce());
      ccxt::any secret = this->base64ToBinary(this->secret);
      ccxt::any auth = add(this->apiKey, nonce);
      headers = ccxt::dict{
          {std::string("X-PCK"), this->apiKey},
          {std::string("X-Stamp"), nonce},
          {std::string("X-Signature"),
           this->hmac(this->encode(auth), secret, sha256,
                      std::string("base64"))},
          {std::string("Content-Type"), std::string("application/json")},
      };
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  ccxt::any handleErrors(ccxt::any code, ccxt::any reason, ccxt::any url,
                         ccxt::any method, ccxt::any headers, ccxt::any body,
                         ccxt::any response, ccxt::any requestHeaders,
                         ccxt::any requestBody) override {
    ccxt::any errorCode =
        this->safeString(response, std::string("code"), std::string("0"));
    ccxt::any message = this->safeString(response, std::string("message"));
    ccxt::any output =
        (isTrue((isEqual(message, ccxt::any{}))) ? ccxt::any(body)
                                                 : ccxt::any(message));
    this->throwExactlyMatchedException(
        ::getValue(this->exceptions, std::string("exact")), message,
        add(add(this->id, std::string(" ")), output));
    if (isTrue(isTrue((!isEqual(errorCode, std::string("0")))) &&
               isTrue((!isEqual(errorCode, std::string("SUCCESS")))))) {
      throw ExchangeError(
          toString(add(add(this->id, std::string(" ")), output)));
    }
    return ccxt::any{};
  }
